window.kbPageData["views/entry/k-fac85f086d6b21bb"] = {"key":"entry/k-fac85f086d6b21bb","state":{"route":"entry/k-fac85f086d6b21bb"},"node":{"id":"k-fac85f086d6b21bb","mode":"k","title":"含析取前件的逆否推理","type":"原理与机制","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":["充分条件假言命题的逆否等价"],"qs":["国考 2024 副省级 行测#115"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"若“A或B”能推出C，则C不成立时，A和B都不成立。这里的“或”表示至少一个成立，否定“至少一个”就得到“两个都不”。","review":{"definition":"若“A或B”能推出C，则C不成立时，A和B都不成立。这里的“或”表示至少一个成立，否定“至少一个”就得到“两个都不”。","explanation":"按三条预测同时成立推理。若甲、乙至少一人通过，条件（3）就推出丙通过、丁不通过。由丁不通过对条件（2）作逆否推理，又得出乙、丙都未通过，与丙通过矛盾。因此甲、乙均未通过，由条件（1）得丙通过，再由条件（2）得丁通过，选A。","references":[],"evidence":"如果乙、丙至少有1人通过，则丁也通过","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 副省级 行测#115":{"paper":"国考 2024 副省级 行测","n":115,"mod":"判断推理","src":["a566fec37e508ca7f975.pdf",24],"asrc":["a475ecf57d968bc14cd6.pdf",37],"card":"db91cd7f45998d250b2a1164","links":[{"id":"k-fac85f086d6b21bb","role":"解题依据","why":"充分条件成立时，否定后件可以推出前件为假。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-fac85f086d6b21bb":[["国考 2024 副省级 行测#115"]]}};
